const SURVIVING_NEIGHBOUR_COUNT = 3;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter(
    (cell) => countNeighbours(cell, liveCells) === SURVIVING_NEIGHBOUR_COUNT,
  );
}

const SURVIVING_NEIGHBOUR_COUNT = 3;

function isNeighbour([ax, ay]: Cell, [bx, by]: Cell): boolean {
  const sameCell = ax === bx && ay === by;
  return !sameCell && Math.abs(ax - bx) <= 1 && Math.abs(ay - by) <= 1;
}

function countNeighbours(cell: Cell, liveCells: Cell[]): number {
  return liveCells.filter((other) => isNeighbour(cell, other)).length;
}

